{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret fastslår korrekt, at vurderingen angår erhvervsevne som uddannelsessøgende og ikke den kommunale arbejdsevnevurdering. Det udelukker korrekt arbejdsprøvning, særlig arbejdspladsindretning, kontakt til arbejdsgivere, studierelevans, lokale forhold/beskæftigelsessituation og erhvervsevnen efter uddannelsen. Det indeholder ingen af rubrikkens materielle fejl. Supplerende oplysninger om tidligere arbejde og skånehensyn stemmer med rubrikkens støtteelementer."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fem kritiske elementer er kommunikeret: målestok (erhvervsevne som uddannelsessøgende med de ressourcer, personen har), ikke kommunal arbejdsevnevurdering, arbejdsprøvning/indretning/arbejdsgiverkontakt, studierelevans/lokale forhold/beskæftigelsessituation og erhvervsevne efter uddannelsen. 'Art og grad' og 'svært ved at finde arbejde' nævnes ikke eksplicit, men dækkes i ækvivalent form af 'funktionsnedsættelsen medfører meget betydelige begrænsninger' og punktet om lokale forhold/beskæftigelsessituation."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler hver af de syv nævnte punkter i spørgsmålet enkeltvis og giver en samlet konklusion. Afsnittet om, hvad der indgår, er relevant supplement."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver identificerbare kilder: SU-loven (LBK nr. 395 af 2023) og vejledning VEJ nr. 10157 af 05/10/2026, med nummererede henvisninger i teksten."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledning 10157 er gyldig og autoritativ. Den angivne lovbestemmelse, SU-loven § 7, stk. 1, nr. 1, er ikke den relevante hjemmel for handicaptillæg. Hjemlen er § 7, stk. 3 i det frosne materiale. Kildelisten indeholder dermed en forkert bestemmelse."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De fleste udsagn om udelukkelser støttes af vejledningens passager (linje 203-210 og 228-233). Påstanden om 'meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde' er knyttet til en forkert lovbestemmelse (§ 7, stk. 1, nr. 1). Dele af sidste afsnit (andre typer arbejde, skånehensyn, mindre omfang, henvisning 8) fremgår ikke af de viste kildepassager. Støtten er derfor ikke fuld."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ikke nye regler, tærskler eller myndigheder af betydning. Tillægget om andre jobtyper, skånehensyn og mindre omfang er ikke i de frosne passager, men er foreneligt med rubrikkens støtteelement om skånehensyn. Det behandles ikke som en væsentlig usupporteret tilføjelse."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer, at vurderingen kun gælder erhvervsevne som uddannelsessøgende. Det bevarer også, at tidligere arbejde 'kan' indgå, og at skånehensyn ved andre jobtyper adskilles fra særlig arbejdspladsindretning. Det udelukker ikke generelt alle skånehensyn."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Punktsvarene, hvad der indgår, og den praktiske konklusion er indbyrdes konsistente. Konklusionen følger af de nævnte distinktioner."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Udelukkelserne gengives som 'indgår ikke', i overensstemmelse med vejledningen. 'Kan indgå' om tidligere arbejde svarer til kilden. 'Det mest nærliggende' i konklusionen og 'som sådan' ved kommunal arbejdsevnevurdering er lidt blødere end kilden, men ændrer ikke betydningen."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker, at handicaptillæg kræver meget betydelige begrænsninger i evnen til erhvervsarbejde, og at der alene tages stilling til erhvervsevne med de ressourcer, personen har. Det dækker også udelukkelsen af arbejdsprøvning, indretning, arbejdsgiverkontakt, studierelevans, lokale forhold, beskæftigelsessituation og erhvervsevne efter uddannelsen. Det mangler ordblindeeksemplet og den eksplicitte udelukkelse af, at det er svært at finde arbejde eller muligt at finde egnet arbejde."
    }
  },
  "overall_notes": "Indholdet er juridisk korrekt og dækker spørgsmålets punkter. Svagheden ligger i kilderne: lovhenvisningen er forkert (§ 7, stk. 1, nr. 1 i stedet for § 7, stk. 3), og en del af det afsluttende afsnit har ikke støtte i de viste passager. Det giver not_met på C05 og C06."
}

